type Msg = { kind: 'a'; x: number } | { kind: 'b'; y: string }

function handle(m: Msg) {
  switch (m.kind) {
    case 'a': return m.x
    case 'b': return m.y.length
    default: {
      const _exhaustive: never = m
      return _exhaustive
    }
  }
}

